// Overview: what was scanned, what the corpus holds, who it runs against, and where the findings stand.
import { h, put, fmt, compact, href, table, notice } from "../lib.js";

const SOURCE_TEXT = {
  "local-core": "generated by a local stellar-core",
  "core-golden": "stellar-core's own goldens",
  history: "captured from network history",
  "history-archive": "history archive (bucket files)",
  "contract-code": "contract code",
  synthetic: "hand-made, marked synthetic",
};
const FAMILY_TEXT = { js: "JavaScript", go: "Go", rust: "Rust", python: "Python" };

// The three results only this kit shows together, each from the site data; a claim is drawn only when the data backs it.
function lead(S, scan) {
  const R = S.replay, B = S.siblings;
  const card = (n, title, body, link, label) => h("a", { class: "lead-card", href: link }, h("span", { class: "n", "aria-hidden": "true" }, n),
    h("strong", null, title), h("span", null, body), h("span", { class: "go" }, label));
  return h("div", { class: "lead-grid" },
    card("1", "Pubnet history, scanned and checked", ["Ledgers ", fmt(scan.first_ledger), " to ", fmt(scan.last_ledger), ": ", fmt(S.scan.failures_total),
      " failures across ", fmt(S.scan.checks), " integrity checks."], href("timeline"), "Ledger history"),
    R && R.pairs && R.pairs_reproduced === R.pairs && R.pairs_current_passes === R.pairs
      ? card("2", "Real incidents, before and after the fix", [fmt(R.pairs), " wallet-backend incidents replayed from corpus entries: each fails before its fix and passes after it and at the current pinned commit."],
        href("replay"), "Replay") : null,
    B && B.top ? card("3", "One defect, every SDK it reaches", ["“", B.top.title, "” reproduces ", B.top.phrase, "."],
      href("siblings", "", { cls: B.top.id }), "One fix, every SDK") : null);
}

export default function overview(root, d) {
  const S = d.summary, scan = d.scan, C = S.corpus, F = S.findings;
  const tile = (v, k, s, link, cls) => h(link ? "a" : "div", { class: "tile" + (cls ? " " + cls : ""), href: link },
    h("span", { class: "v" }, v), h("span", { class: "k" }, k), s ? h("span", { class: "s" }, s) : null);

  put(root, 
    h("h1", null, "XDRCheck: rare ledger shapes, their CAPs, and who misreads them"),
    h("p", { class: "lede" }, "A corpus of rare but valid Stellar ledger and transaction shapes, each tagged with its CAP and ",
      "protocol; a scan of pubnet history from ledger ", fmt(scan.first_ledger), " to ", fmt(scan.last_ledger), " with its integrity checks, its shape census and ",
      "how often each entry's shape occurs on mainnet; and the results of running the corpus ",
      "through SDKs and indexing pipelines. Pick a view above, or start from a CAP."),

    lead(S, scan),

    h("h2", null, "The pubnet scan"),
    h("p", null, "Every ledger from ", fmt(scan.first_ledger), " to ", fmt(scan.last_ledger),
      " was read from the public data lake, decoded, re-encoded byte for byte and checked. The scan computes shapes and ",
      "checks only; the pipelines and SDKs were run on the corpus, not on all of mainnet."),
    h("div", { class: "tiles" },
      tile(fmt(scan.ledgers), "ledgers read", "protocols " + scan.protocol_min + " to " + scan.protocol_max, href("timeline")),
      tile(compact(scan.transactions), "transactions", fmt(scan.transactions)),
      tile(fmt(S.scan.failures_total), "failures across " + S.scan.checks + " integrity checks",
        fmt(S.scan.hash_links) + " hash-chain links checked", null, S.scan.failures_total === 0 ? "ok" : null),
      tile(fmt(scan.shapes.tx_component_shapes_g3), "transaction-level component shapes",
        fmt(scan.shapes.whole_tx_shapes_g3) + " whole-transaction shapes; " + fmt(scan.shapes.tokens) + " tokens"),
      scan.mainnet_tier ? tile(fmt(scan.mainnet_tier.tier_tokens) + " / " + fmt(scan.mainnet_tier.tokens),
        "transaction-level tokens held by the mainnet tier",
        fmt(scan.mainnet_tier.tier_transactions) + " real pubnet transactions; the curated corpus holds " +
        fmt(scan.mainnet_tier.curated_tokens)) : null),
    table(["Check", { t: "Checked", cls: "num" }, { t: "Failures", cls: "num" }],
      scan.checks.map((c) => h("tr", null, h("td", null, c.check), h("td", { class: "num" }, fmt(c.checked) + " " + c.unit),
        h("td", { class: "num" }, fmt(c.failures)))), { label: "Integrity checks of the scan" }),
    h("p", { class: "caption" }, "Source: ", h("code", null, scan.source), ". Ledger 2's previous-ledger hash names ledger 1, which is not in the run."),
    scan.mainnet_tier ? h("p", null, "The mainnet tier is a list of real pubnet transactions, located in the public data lake, that ",
      "together hold every transaction-level shape token the scan found (",
      fmt(scan.mainnet_tier.tier_tokens), " of ", fmt(scan.mainnet_tier.tokens), "); the curated corpus holds ",
      fmt(scan.mainnet_tier.curated_tokens), " of them. The tier is not a result of any SDK or pipeline run. What it claims and what it does not: ",
      h("code", null, scan.mainnet_tier.tier), "; source: ", h("code", null, scan.mainnet_tier.source), ".") : null,

    h("h2", null, "The corpus"),
    h("div", { class: "tiles" },
      tile(fmt(C.entries), "corpus entries", "version " + C.version, href("caps")),
      tile(fmt(C.core_emitted), "emitted by stellar-core", "local core, goldens or network history"),
      tile(fmt(C.twins), "on both passphrases", "testnet and pubnet twins"),
      tile(fmt(C.cap_rows_with_entries) + " / " + fmt(C.cap_rows), "CAP rows with entries",
        fmt(C.rows_with_entries) + " of " + fmt(C.rows) + " rows in all", href("caps")),
      tile(fmt(C.core_protocols), "protocol versions", "among the core-emitted variants"),
      tile(fmt(C.synthetic), "marked synthetic", "hand-made, flagged in the manifest"),
      S.entry_prevalence ? tile(fmt(S.entry_prevalence.never_seen_on_mainnet), "never seen on mainnet",
        "their rarest shape token is not in the scanned range", href("rarity", "", { group: "never" })) : null,
      S.golden ? tile(fmt(S.golden.transaction_tier) + " + " + fmt(S.golden.operation_tier), "local-core entries that match stellar-core's goldens",
        "on the whole transaction, or on every operation", href("caps") + "") : null),
    h("div", { class: "cols" },
      h("div", null, h("h3", null, "Entries by source"),
        table(["Source", { t: "Entries", cls: "num" }, ""], Object.entries(C.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) =>
          h("tr", null, h("td", null, SOURCE_TEXT[k] || k), h("td", { class: "num" }, fmt(v)),
            h("td", null, h("span", { class: "bar-h", style: "width:" + Math.round(140 * v / C.entries) + "px", "aria-hidden": "true" })))),
          { label: "Entries by source" }),
        h("p", { class: "caption" }, "An entry counts under every source one of its variants has.")),
      h("div", null, h("h3", null, "Shapes behind known defects"),
        table(["Shape", { t: "Entries", cls: "num" }], C.risk_shapes.map((s) =>
          h("tr", null, h("td", null, h("a", { href: href("sdk", "", { shape: s.key }) }, s.label)), h("td", { class: "num" }, fmt(s.entries)))),
          { label: "Shapes behind known defects" }))),

    h("h2", null, "What the corpus runs against"),
    h("div", { class: "cards" },
      h("div", { class: "card" }, h("h3", null, "SDK conformance"),
        h("p", null, fmt(S.sdk.columns_public), " columns in the public set (", fmt(S.sdk.columns_pr), " on every pull request, ",
          fmt(S.sdk.columns_required), " required):"),
        h("dl", { class: "kv" }, Object.entries(S.sdk.families).flatMap(([k, v]) => [h("dt", null, FAMILY_TEXT[k] || k), h("dd", { class: "mono" }, v.join(", "))])),
        h("a", { href: href("sdk") }, "SDK matrix")),
      h("div", { class: "card" }, h("h3", null, "Pipelines"),
        h("p", null, "Replayed through the harness: ", S.pipelines.replayed.join(" and "), ". Service rigs: ", S.pipelines.rigs.join(", "), "."),
        h("p", null, fmt(S.pipelines.acceptance_pairs), " known wallet-backend defects reproduced on their pre-fix commits and passing on the fixed ones."),
        h("a", { href: href("replay") }, "Replay")),
      h("div", { class: "card" }, h("h3", null, "Linter"),
        h("p", null, fmt(S.lint.rules), " xdrlint rules (", fmt(S.lint.default_rules), " in the default set) for the three ingestion mistakes: ",
          "trusting unvalidated fields, missing depth and size caps, participants from the envelope instead of the meta."),
        h("a", { href: href("problems", "", { tab: "rules" }) }, "Rules"))),

    h("h2", null, "Findings"),
    h("div", { class: "tiles" },
      tile(fmt(F.filed), "filed upstream by this kit", "in " + fmt(F.filed_projects) + " projects", href("problems", "", { state: "filed" })),
      tile(fmt(F.known_upstream), "already known upstream", null, href("problems", "", { state: "duplicate-of" })),
      tile(fmt(F.not_a_defect), "reviewed, not a defect", null, href("problems", "", { state: "not-a-defect" })),
      tile(fmt(F.records), "public finding records", null, href("problems"))),
    F.awaiting_review_total ? notice("Awaiting review:", fmt(F.awaiting_review_total) +
      " entries of the repository's pending lists wait on finding review. Only their number is shown here.") : null,
  );
  const missing = Object.entries(S.results).filter(([, v]) => !v).map(([k]) => k);
  if (missing.length) {
    put(root, h("p", { class: "caption" }, "Result files not in the repository yet: ", missing.join(", "),
      ". The views that use them say what they show instead."));
  }
  return "Overview";
}
